# Fails if a static library in the given directory references a vectorized helper of the MSVC STL (__std_rotate, __std_min_element_1u, ...).
# __std_exception_copy and __std_terminate are not among them: every toolset has those.
# They only exist in the msvcprt.lib of newer Visual Studio toolsets, so programs fail to link with an older one. The names are plain text
# in the symbol table of a library, and nothing of ours defines them, so any occurrence is a reference.
set -u
found=0
while IFS= read -r -d '' lib; do
	names=$(grep -aoE '__std_(adjacent_find|bitset|count|find|includes|is_sorted|max|min|minmax|mismatch|remove|replace|reverse|rotate|search|swap_ranges|unique)[a-z0-9_]*' "$lib" | sort -u | tr '\n' ' ')
	if [ -n "$names" ]; then
		echo "error: $lib references $names" >&2
		found=1
	fi
done < <(find "${1:?directory}" -name '*.lib' -print0)
exit $found
